const s2u5QuestionRange = (from: number, to: number) =>
  Object.keys(S2_UNIT5_QUESTIONS)
    .filter((key) => {
      const match = key.match(/^s2u5_(\d{3})_/);
      if (!match) return false;

      const number = Number(match[1]);
      return number >= from && number <= to;
    })
    .sort((a, b) => {
      const aNumber = Number(a.match(/^s2u5_(\d{3})_/)?.[1] ?? 0);
      const bNumber = Number(b.match(/^s2u5_(\d{3})_/)?.[1] ?? 0);

      return aNumber - bNumber;
    });

